```javascript
/**
 * Recalcula el valor de todas las celdas que contienen fórmulas basándose en los valores actuales del spreadsheet.
 */
function calculateAllFormulas() {
    const spreadsheet = document.getElementById('spreadsheet');
    if (!spreadsheet) return;

    // 1. Obtener todos los valores actuales de las celdas (data map: "A1": value, "B1": value...)
    const cellValues = {};
    let cells = spreadsheet.querySelectorAll('td[contenteditable="true"]');
    cells.forEach(cell => {
        // Usamos el contenido textual para obtener el valor más reciente
        const content = cell.textContent.trim();
        const id = `${cell.dataset.col}${cell.dataset.row}`; 
        cellValues[id] = content;
    });

    /** Función auxiliar para escapar caracteres de regex */
    function escapeRegExp(string) {
      return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    }

    // 2. Iterar sobre las celdas y recalcular fórmulas
    cells.forEach(cell => {
        const content = cell.textContent.trim();
        if (content && content.startsWith('=')) {
            let formula = content; // Incluye el '=' para la detección inicial
            let calculatedValue = null;

            // Sustituir referencias de celda en la fórmula por sus valores actuales
            let expression = formula.substring(1); // Quitamos '='

            // Ordenar IDs para evitar reemplazar B1 dentro de A1 si ambos existen
            const sortedKeys = Object.keys(cellValues).sort((a, b) => {
                return (a === 'A' ? -1 : 1) * (b === 'A' ? 1 : -1); // Simple sorting heuristic
            });

            for (const id of sortedKeys) {
                const cellId = `${id[0]}${id[1]}`; // e.g., A1
                const value = cellValues[cellId];
                if (value !== undefined && !isNaN(parseFloat(value))) {
                    // Reemplazar todas las ocurrencias de la referencia celular con su valor numérico actual
                    let regex = new RegExp(`\\b${escapeRegExp(cellId)}\\b`, 'g');
                    expression = expression.replace(regex, value);
                }
            }

            try {
                // Evaluar la expresión matemática resultante (ej: "2+3")
                calculatedValue = Function(`return ${expression}`)();
            } catch (e) {
                console.warn("Error al calcular fórmula:", e);
                // Si falla el cálculo, mantenemos la fórmula original en lugar de actualizarla con NaN.
                return; 
            }

            const newValueString = calculatedValue.toString();

            // Solo actualizamos si hay un cambio real o si necesitamos forzar la actualización del valor calculado.
            if (cell.textContent !== newValueString) {
                 cell.textContent = newValueString;
            }
        }
    });
}
