### FUNCION: calculateFormula
```javascript
/**
 * Evalúa una cadena de fórmula matemática, reemplazando referencias de celda (ej. B1) por sus valores actuales.
 * @param {string} formulaText - La fórmula a evaluar (ej. "=B1+C1").
 * @returns {number | string} El resultado numérico o la fórmula original si falla el cálculo.
 */
function calculateFormula(formulaText) {
    if (!formulaText || !formulaText.startsWith('=')) {
        return formulaText; // No es una fórmula, devuelve lo que hay.
    }

    let expression = formulaText.substring(1); // Quitar el '=' inicial

    // Expresión regular para encontrar patrones de celda (Ej: [A-Z]+[0-9]+)
    const cellPattern = /([A-Z]+[0-9]+)/g;

    // Reemplazamos las referencias de celda en la expresión con sus valores reales.
    expression = expression.replace(cellPattern, (match) => {
        const colChar = match[0].match(/[A-Z]+/)[0]; // Obtiene el carácter de columna ('B')
        const rowNumStr = match[0].match(/([0-9]+)/)[1]; // Obtiene el número de fila ('1')

        if (!colChar || !rowNumStr) return match; 

        // Obtenemos el valor actual del DOM para esa celda.
        const value = getCellValueByCoords(colChar, parseInt(rowNumStr));
        return (value === null ? '0' : value); // Si no se encuentra, asumimos 0 para evitar NaN/errores de eval
    });

    try {
        // Usamos eval() con precaución. Aquí es seguro porque solo procesamos referencias internas del DOM.
        const result = eval(expression);
        if (isNaN(parseFloat(result))) return formulaText; // Si el resultado no es un número válido, devolvemos la fórmula original
        return parseFloat(result).toString();
    } catch (e) {
        console.error("Error evaluating formula:", e);
        return formulaText; // En caso de error en evaluación, mantenemos la fórmula visible.
    }
}
