function setupColorPicker() {
    const controls = document.getElementById('cell-controls');
    if (!controls) return;

    const colorButton = document.getElementById('colorPickerBtn');
    const colorPanel = document.getElementById('colorPanel');

    // 1. Listener para mostrar/ocultar el panel al hacer clic en el botón de color.
    colorButton.addEventListener('click', (e) => {
        e.stopPropagation(); // Prevenir que el click se propague a la ventana y cierre el menú.
        const isVisible = colorPanel.style.display === 'block';
        if (isVisible) {
            colorPanel.style.display = 'none';
        } else {
            // Posicionar panel cerca del botón de control o en una ubicación visible.
            // Lo posicionaremos justo debajo del contenedor principal.
            const rect = colorButton.getBoundingClientRect();
            colorPanel.style.top = `${rect.bottom + 10}px`;
            colorPanel.style.left = `${rect.left}px`;
            colorPanel.style.display = 'block';
        }
    });

    // 2. Generar y añadir opciones de color.
    const defaultColors = ['#FFFFFF', '#FFD700', '#ADD8E6', '#F08080', '#90EE90']; // Blanco, Dorado, Azul claro, Rosa claro, Verde claro

    defaultColors.forEach(color => {
        const colorBox = document.createElement('div');
        colorBox.style.width = '30px';
        colorBox.style.height = '30px';
        colorBox.style.backgroundColor = color;
        colorBox.style.border = '1px solid #ccc';
        colorBox.style.cursor = 'pointer';
        colorBox.dataset.color = color;

        // Listener para aplicar el color al hacer click en la caja de color.
        colorBox.addEventListener('click', () => {
            const selectedColor = colorBox.dataset.color;
            applyBackgroundColor(selectedColor);
            colorPanel.style.display = 'none'; // Ocultar panel después de seleccionar un color
        });

        colorPanel.appendChild(colorBox);
    });

    // 3. Listener global para cerrar el panel si se hace clic fuera de él.
    document.addEventListener('click', (e) => {
        if (!colorButton.contains(e.target) && !colorPanel.contains(e.target)) {
            colorPanel.style.display = 'none';
        }
    });
}
