function handleContextMenu(event) {
    // Prevenir el menú contextual predeterminado del navegador
    event.preventDefault(); 
    const target = event.target;

    // Solo actuar si se hace clic derecho sobre una celda de datos editable (TD).
    if (target.tagName === 'TD' && target.hasAttribute('contenteditable')) {
        const cell = target;

        // Limpiar cualquier menú anterior y añadir el nuevo evento de cierre global.
        document.querySelectorAll('.context-menu').forEach(el => el.remove());
        document.removeEventListener('click', handleMenuClickOutside);

        // 1. Crear la estructura del menú contextual
        const menu = document.createElement('div');
        menu.className = 'context-menu';
        menu.style.position = 'absolute';
        menu.style.zIndex = '1000';
        menu.style.backgroundColor = '#fff';
        menu.style.border = '1px solid #ccc';
        menu.style.boxShadow = '2px 2px 5px rgba(0,0,0,0.2)';
        menu.style.padding = '8px';

        // Posicionar el menú cerca del cursor
        menu.style.top = `${event.clientY}px`;
        menu.style.left = `${event.clientX}px`;


        let htmlContent = `<h4>Formato Celda</h4><hr style="margin: 5px 0;"><label>Color de Fondo:</label><div class="color-palette" style="display: flex; gap: 8px; margin-top: 10px;"></div>`;
        menu.innerHTML = htmlContent;
        const paletteContainer = menu.querySelector('.color-palette');

        // Colores de ejemplo para la prueba
        const defaultColors = ['#FF0000', '#00FF00', '#0000FF', '#FFFF00'];

        defaultColors.forEach(color => {
            const swatch = document.createElement('div');
            swatch.className = 'color-swatch';
            swatch.style.width = '30px';
            swatch.style.height = '30px';
            swatch.style.backgroundColor = color;
            swatch.dataset.color = color;
            // Asignar el evento al swatch para aplicar el color
            swatch.addEventListener('click', () => applyBackgroundColor(cell, color));
            paletteContainer.appendChild(swatch);
        });

        document.body.appendChild(menu);

        // 2. Función de manejo del click fuera del menú
        const handleMenuClickOutside = (e) => {
            if (!menu.contains(e.target)) {
                menu.remove();
                document.removeEventListener('click', handleMenuClickOutside);
            }
        };
        document.addEventListener('click', handleMenuClickOutside);

    } else {
        // Si no se hace clic derecho sobre una celda válida, simplemente ignorar el evento.
    }
}
