function selectColumn(columnLetter) {
    const spreadsheet = document.getElementById('spreadsheet');
    if (!spreadsheet) return;

    // 1. Deseleccionar columna activa y limpiar estilos de las celdas
    document.querySelectorAll('.col-header').forEach(th => th.style.backgroundColor = '');
    document.querySelectorAll('.selected-column td').forEach(td => {
        td.style.backgroundColor = ''; // Limpiar fondo
    });

    // 2. Seleccionar la nueva columna
    const headerElement = document.querySelector(`.col-header[data-col="${columnLetter}"]`);
    if (!headerElement) return;

    activeColumn = columnLetter;
    headerElement.style.backgroundColor = '#cce5ff'; // Color de selección visual

    // Aplicar clase a todas las celdas de la columna en el tbody para facilitar futuras manipulaciones
    const rows = spreadsheet.querySelectorAll('tbody tr');
    rows.forEach(row => {
        const cell = row.querySelector(`[data-col="${columnLetter}"]`);
        if (cell) {
            cell.classList.add('selected-column');
        } else {
             // Si el selector falla, asegurar que la celda exista y esté lista para ser manipulada
        }
    });

    console.log(`Columna ${columnLetter} seleccionada.`);
}
