### FUNCION: deleteColumn
```javascript
function deleteColumn() {
    if (!activeColumn) {
        alert("Por favor, selecciona una columna primero.");
        return;
    }

    if (!confirm(`¿Estás seguro de que deseas eliminar permanentemente la columna ${activeColumn}? Esta acción no se puede deshacer.`)) {
        return;
    }

    const spreadsheet = document.getElementById('spreadsheet');
    const headerRow = spreadsheet.querySelector('thead tr');
    const columnHeaderCell = headerRow.querySelector(`.col-header[data-col="${activeColumn}"]`);

    if (!columnHeaderCell) return;

    // 1. Eliminar el encabezado de la columna
    columnHeaderCell.remove();

    // 2. Iterar sobre todas las filas (tbody tr) y eliminar la celda correspondiente
    const rows = spreadsheet.querySelectorAll('tbody tr');
    rows.forEach(row => {
        const cellToRemove = row.querySelector(`[data-col="${activeColumn}"]`);
        if (cellToRemove) {
            cellToRemove.remove();
        }
    });

    // Limpiar estado
    activeColumn = null;
    console.log(`Columna ${activeColumn} eliminada exitosamente.`);
}
