```javascript
/**
 * Borra el contenido de todas las celdas en una columna dada.
 * @param {string} columnLetter - La letra de la columna (Ej: 'A').
 */
function clearColumnContent(columnLetter) {
    const spreadsheet = document.getElementById('spreadsheet');
    if (!spreadsheet) return;

    // 1. Limpiar el encabezado (Aunque solo debe tener texto, por seguridad si fuera editable)
    const headerTH = spreadsheet.querySelector('.col-header[data-col="' + columnLetter + '"]');
    if (headerTH) {
        // Solo limpiamos contenido de la celda, no eliminamos el label (A, B, C...)
        headerTH.textContent = ''; 
    }

    // 2. Limpiar todas las celdas de datos (TD)
    const rows = spreadsheet.querySelectorAll('tbody tr');
    rows.forEach(row => {
        let targetCell = null;
        // Buscar la TD que corresponde a esta columna en la fila actual usando data-col
        for (const cell of row.querySelectorAll('td')) {
            if (cell.dataset.col === columnLetter) {
                targetCell = cell;
                break;
            }
        }
        if (targetCell) {
            targetCell.textContent = '';
        }
    });

    console.log(`Contenido de la columna ${columnLetter} limpiado.`);
}
```

