### FUNCION: selectRow
```javascript
let selectedRow = null;

function selectRow(event) {
    const header = event.target.closest('.row-header');
    if (!header) return;

    // Target is the row containing the clicked header
    const row = header.closest('tr'); 

    // Deselect previous row visually
    document.querySelectorAll('#spreadsheet tbody tr').forEach(r => {
        r.classList.remove('selected-row');
    });

    // Select current row and store it
    row.classList.add('selected-row');
    selectedRow = row;
}
```

### FUNCION: clearRowContent
```javascript
function clearRowContent() {
    if (!selectedRow) {
        alert("Please select a row first.");
        return;
    }
    const cells = selectedRow.querySelectorAll('td');
    cells.forEach(cell => {
        cell.textContent = '';
    });
}
```

### FUNCION: deleteSelectedRow
```javascript
function deleteSelectedRow() {
    if (!selectedRow) {
        alert("Please select a row to delete.");
        return;
    }
    // Confirmation step before deletion
    if (confirm("Are you sure you want to permanently delete this entire row?")) {
        selectedRow.remove();
        selectedRow = null;
    }
}
