let selectedRow = null;

function selectRow(event) {
    const header = event.target.closest('.row-header');
    if (!header) return;

    // Target is the row containing the clicked header
    const row = header.closest('tr'); 

    // Deselect previous row visually
    document.querySelectorAll('#spreadsheet tbody tr').forEach(r => {
        r.classList.remove('selected-row');
    });

    // Select current row and store it
    row.classList.add('selected-row');
    selectedRow = row;
}

function clearRowContent() {
    if (!selectedRow) {
        alert("Please select a row first.");
        return;
    }
    const cells = selectedRow.querySelectorAll('td');
    cells.forEach(cell => {
        cell.textContent = '';
    });
}

function deleteSelectedRow() {
    if (!selectedRow) {
        alert("Please select a row to delete.");
        return;
    }
    // Confirmation step before deletion
    if (confirm("Are you sure you want to permanently delete this entire row?")) {
        selectedRow.remove();
        selectedRow = null;
    }
}

function changeBackgroundColor() {
    if (!selectedRow) {
        alert("Please select a row first.");
        return;
    }
    const cells = selectedRow.querySelectorAll('td');
    // Apply a distinct background color to all data cells in the selected row
    cells.forEach(cell => {
        cell.style.backgroundColor = 'rgba(255, 200, 100, 0.3)'; // Light yellow/orange highlight
    });
}

function setupRowSelectionAndActions() {
    const spreadsheetBody = document.querySelector('#spreadsheet tbody');
    if (!spreadsheetBody) return;

    // 1. Handle Row Selection (Click on the row number header)
    spreadsheetBody.addEventListener('click', (e) => {
        if (e.target.closest('.row-header')) {
            selectRow(e);
        }
    });

    // 2. Attach action listeners to controls
    document.getElementById('clearContentBtn').addEventListener('click', clearRowContent);
    document.getElementById('changeColorBtn').addEventListener('click', changeBackgroundColor);
    document.getElementById('deleteRowBtn').addEventListener('click', deleteSelectedRow);
}
